import {developmentData,developmentPaths} from './development-data.js?v=20261026-development01';
export {developmentData,developmentPaths};
export const globalDevelopmentViews={
 'dev-definitions':[['output','Output per person'],['capabilities','People’s opportunities'],['voice','Political participation'],['bridge','Resources into services']],
 'dev-factors':[['security','Food and water'],['technology','Useful connections'],['inclusion','Access and inclusion'],['opportunity','Investment and opportunity']],
 'dev-measures':[['gdp','GDP per capita'],['hdi','Human Development Index'],['inequality','Income distribution'],['cpi','Corruption perceptions']],
 'dev-patterns':[['world','World HDI map'],['countries','Compare countries'],['within','Within a country'],['uk','UK regional income']],
 'dev-causes':[['physical','Physical connections'],['history','Historical legacies'],['economy','Economic concentration'],['compare','Build an explanation']]
};
export const globalDevelopmentRequirements=Object.fromEntries(Object.entries(globalDevelopmentViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const globalDevelopmentAnimated=(k,v)=>k==='dev-definitions'?['output','bridge'].includes(v):k==='dev-factors'?true:k==='dev-measures'?v==='inequality':k==='dev-causes'?v!=='compare':false;
export const outputPerPerson=(output,population)=>population>0?output/population:0;
export const incomeDistribution=t=>{t=Math.min(1,Math.max(0,Number(t)||0));return [20-15*t,20-15*t,20-15*t,20-15*t,20+60*t];};
export function gini(values){const s=[...values].sort((a,b)=>a-b),n=s.length,total=s.reduce((a,b)=>a+b,0);return n&&total>0?100*(2*s.reduce((sum,v,i)=>sum+(i+1)*v,0)/(n*total)-(n+1)/n):0;}
export const hdiCategory=v=>!Number.isFinite(v)?'missing':v<.55?'Low':v<.7?'Medium':v<.8?'High':'Very High';
const T=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#b5ced1',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#efb89d')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#e5e9df"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?65:43}" rx="11" fill="#35576a" stroke="#a4bdc6"/>`+T(x+10,y+26,a,12)+(b?T(x+10,y+49,b,11):'');
const title=s=>T(20,29,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#eef2ed" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const source=k=>`<p class="geo-caption">${{
 definition:link('https://hdr.undp.org/about/human-development','UNDP: human development and opportunities')+'. Diagrams are teaching examples, not measured national outcomes.',
 hdi:link(developmentData.hdi.source,'UNDP HDR 2025: 2023 HDI values')+' · '+link('https://creativecommons.org/licenses/by/3.0/igo/','CC BY 3.0 IGO')+'. Adapted selection/chart. Health, schooling and GNI dimension indices; not GDP or a complete wellbeing measure.',
 gdp:link(developmentData.gdp.source,'World Bank WDI: GDP per capita, PPP, 2023')+' · CC BY 4.0. Current international dollars/person, rounded for display; not wages, GNI or constant-price growth.',
 uk:link(developmentData.uk.source,'ONS: regional GDHI, 19 August 2026 release')+' · OGL v3.0. 2024 provisional, current £/person; household-sector averages, not wages or money left after rent; no regional price adjustment.',
 cpi:link(developmentData.cpi.source,'Transparency International: CPI 2025, released 10 February 2026')+'. Public-sector corruption perceptions, 0 highly corrupt → 100 very clean; not a percentage of corrupt people.',
 transport:link('https://www.wto.org/english/res_e/publications_e/landlocked2021_e.htm','WTO: landlocked trade and connectivity')+' · '+link('https://www.un.org/ohrlls/node/987','UN-OHRLLS: geographical constraints and transit')+'. Illustrative mechanism; not measured costs or an inevitable development path.',
 economy:link('https://apps.london.gov.uk/state-of-london/report/economy','GLA: London industry, productivity and investment')+' · '+link('https://www.worldbank.org/en/topic/infrastructure/publication/shrinking-economic-distance-understanding-how-markets-and-places-can-lower-transport-costs-in-developing-countries','World Bank: transport and markets')+'. Mechanisms are simplified, not equal benefits or measured causal effects.'
 }[k]}</p>`;
const table=(caption,headers,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${caption}</caption><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const short=n=>n==='United Kingdom'?'UK':n;
const dataColours={'Low':'#dce4d5','Medium':'#a8c4b2','High':'#e7bba0','Very High':'#ed8b75','missing':'#607483'};
export function developmentMap(){const byCode=new Map(developmentData.hdi.countries.map(c=>[c.code,c]));let b=title('WORLD · NATIONAL HUMAN DEVELOPMENT INDEX')+T(20,49,'2023 scores · HDR 2025 · generalised country geometry',11);for(const p of developmentPaths){const v=byCode.get(p.code)?.hdi;b+=`<path d="${p.d}" fill="${dataColours[hdiCategory(v)]}" stroke="#294657" stroke-width="0.4"><title>${p.name}: ${Number.isFinite(v)?v.toFixed(3):'no matched data'}</title></path>`;}const labs=[['Low','&lt;0.550'],['Medium','0.550–0.699'],['High','0.700–0.799'],['Very High','≥0.800']];for(let i=0;i<4;i++)b+=`<rect x="${20+i*103}" y="280" width="10" height="10" fill="${dataColours[labs[i][0]]}"/>`+T(35+i*103,290,labs[i][0],11)+T(20+i*103,309,labs[i][1],10);b+=T(20,334,'Grey: missing/unmatched · map area is not population',11);return fig(b,'Country-level HDI categories on real Natural Earth 110m outlines, public domain. Equirectangular display distorts area; national averages conceal within-country differences. No data are inferred for grey areas.')+source('hdi')+`<p class="geo-caption">${link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth: public domain geometry')}. Antarctica omitted. Adaptation: projection and attribute join.</p>`;}
export function developmentEvidence(kind='pair'){
 if(kind==='world')return developmentMap();
 if(kind==='pair')return `<table class="geo-data"><caption>Six selected countries · 2023 values</caption><thead><tr><th scope="col">Country</th><th scope="col">GDP/person<br>PPP int.$</th><th scope="col">HDI<br>0–1</th></tr></thead><tbody>${developmentData.gdp.selected.map(c=>`<tr><th scope="row">${short(c.name)}</th><td>${Math.round(c.gdp).toLocaleString('en-GB')}</td><td>${c.hdi.toFixed(3)}</td></tr>`).join('')}</tbody></table>`+source('gdp')+source('hdi');
 if(kind==='uk'){const chosen=['London','South East','North East','Wales','Scotland','Northern Ireland'];const rows=chosen.map(name=>developmentData.uk.regions.find(r=>r.name===name));let b=title('UK · HOUSEHOLD INCOME PER PERSON')+T(20,51,'2024 provisional · current £ · zero-based bars',11);for(const[r,i]of rows.map((r,i)=>[r,i]))b+=T(20,86+i*38,r.name,11)+`<rect x="125" y="${72+i*38}" width="${r.value/40000*230}" height="20" fill="#abc7b4"/>`+T(135+r.value/40000*230,86+i*38,r.value.toLocaleString('en-GB'),11);b+=T(20,330,'UK benchmark: £25,965 per person',12);return fig(b,'Selected ITL1 regional means, not individual household incomes. Same year, measure and pounds per person; does not adjust for regional living costs.')+source('uk')+table('ONS 2024 GDHI per head, provisional',['Region','£ / person'],[...rows,{name:'UK',value:25965}].map(r=>[r.name,r.value.toLocaleString('en-GB')]))}
 const d=kind==='cpi'?developmentData.cpi.countries:developmentData.gdp.selected;const isHdi=kind==='hdi',max=kind==='cpi'?100:isHdi?1:140000;let b=title(kind==='cpi'?'PERCEIVED PUBLIC-SECTOR CORRUPTION':isHdi?'HUMAN DEVELOPMENT INDEX':'GDP PER CAPITA · PURCHASING POWER PARITY')+T(20,52,kind==='cpi'?'CPI 2025 · 0–100 scale':isHdi?'2023 · 0–1 scale · HDR 2025':'2023 · current international $ / person',11);const ys=kind==='cpi'?50:36;for(let i=0;i<d.length;i++){const c=d[i],v=kind==='cpi'?c.score:isHdi?c.hdi:c.gdp,x=120,w=v/max*230;b+=T(20,92+i*ys,short(c.name),12)+`<rect x="${x}" y="${77+i*ys}" width="${w}" height="20" fill="${isHdi?'#efb89d':'#abc7b4'}"/>`+T(x+w+7,92+i*ys,isHdi?v.toFixed(3):Math.round(v).toLocaleString('en-GB'),11);}b+=line(`M120 306H350`,'#a3bfc5',1)+T(120,326,'0',10)+T(305,326,isHdi?'1.000':kind==='cpi'?'100':'140,000',10);const c=kind==='cpi'?'Higher score means lower perceived public-sector corruption. Four selected countries; scores are not percentages of corrupt residents.':isHdi?'National average HDI, not a direct measure of inequality or political freedom. Selected countries only; larger index values indicate higher average achievement.':'GDP output per person, not wages. Six selected countries and one reference year; PPP accounts for price-level differences, not changes in prices over time.';return fig(b,c)+source(kind==='cpi'?'cpi':isHdi?'hdi':'gdp')+table('Selected values',['Country',isHdi?'HDI':kind==='cpi'?'CPI score':'PPP int.$ / person'],d.map(c=>[short(c.name),isHdi?c.hdi.toFixed(3):kind==='cpi'?String(c.score):Math.round(c.gdp).toLocaleString('en-GB')]));
}
const people=(x,y)=>Array.from({length:3},(_,i)=>dot(x+i*28,y,8,'#b3cbbb')+line(`M${x+i*28} ${y+12}v28m-9-19h18`,'#b3cbbb',4)).join('');
const school=(x,y)=>`<path d="M${x} ${y}l38-25 38 25v65h-76Z" fill="#d1b59d" stroke="#e6e4d7"/><rect x="${x+28}" y="${y+30}" width="20" height="35" fill="#29475b"/>`;
export function globalDevelopmentScene(k,v,t=0){if(!globalDevelopmentViews[k])return '';if(!globalDevelopmentRequirements[k].includes(v))v=globalDevelopmentRequirements[k][0];t=globalDevelopmentAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',src='definition';
 if(k==='dev-measures'&&v!=='inequality')return developmentEvidence(v);
 if(k==='dev-patterns'&&v==='world')return developmentMap();if(k==='dev-patterns'&&v==='uk')return developmentEvidence('uk');if(k==='dev-patterns'&&v==='countries')return developmentEvidence('hdi');
 if(k==='dev-definitions'){
 if(v==='output'){const n=Math.round(t*10),g=200+10*n,p=10000+500*n;b=title('BIGGER TOTAL, SAME OUTPUT PER PERSON')+T(20,90,'Output: '+g.toFixed(0)+' million teaching units',15)+`<rect x="20" y="105" width="${g}" height="26" fill="#eabc9c"/>`+T(20,180,'Population: '+p.toLocaleString('en-GB',{maximumFractionDigits:0}),15)+people(45,220)+T(20,310,'Per person: '+outputPerPerson(g*1e6,p).toLocaleString('en-GB')+' units',16);c='Invented economy: output 200→300 million and population 10,000→15,000 rise proportionately. Output per person stays 20,000; this is not household wages or real national data.';}
 else if(v==='capabilities'){b=title('WHAT CAN PEOPLE ACTUALLY DO?')+school(170,140)+box(20,65,175,'Healthy lives','Safe care / nutrition')+box(245,65,175,'Knowledge','Schooling / learning')+box(20,260,400,'Access to opportunities matters','Income can help; distribution and provision matter');c='A static capabilities framework. Resources can support health and education, but an income average alone does not guarantee usable opportunities for everyone.';}
 else if(v==='voice'){b=title('POLITICAL OPPORTUNITIES MATTER TOO')+people(185,95)+box(20,185,190,'Participation','Can people have a say?')+box(230,185,190,'Accountability','Can decisions be challenged?')+T(20,305,'Rights and freedoms need several kinds of evidence.',12);c='A static comparison of political opportunities. Participation and accountability are broader than the size of the economy or a single turnout statistic.';}
 else{b=title('RESOURCES CAN SUPPORT PUBLIC SERVICES')+box(20,65,180,'Economic resources','Income / public revenue')+box(240,65,180,'Public choices','Allocation / upkeep')+school(190,235)+line('M200 100H240M330 140L240 220')+dot(200+40*t,100)+dot(330-90*t,140+80*t)+T(20,325,'Benefits depend on access, quality and who is included.',11);c='A possible resource→decision→service pathway. Tokens illustrate sequence, not a tax rate, budget or guaranteed improvement.';}
 }
 if(k==='dev-factors'){
 if(v==='security'){b=title('BASIC SECURITY SUPPORTS PARTICIPATION')+`<path d="M70 70Q30 125 70 140Q110 125 70 70Z" fill="#a7cbd0"/><path d="M145 135V75m0 25l-15-12m15 26 16-15" stroke="#c4d3ae" stroke-width="4"/>`+school(300,190)+box(20,205,200,'Food / safe water','Nutrition / health / time')+line('M160 110Q255 105 325 180')+dot(160+165*t,110+70*t)+T(20,320,'Possible pathway: health and time → school / work',11);c='Illustrative food/water-security pathway. Reliable access supports health and participation; timings are symbolic and do not guarantee learning or employment.';}
 else if(v==='technology'){b=title('A CONNECTION MUST BE USABLE')+`<rect x="30" y="95" width="105" height="78" rx="8" fill="#acc1be"/><rect x="40" y="105" width="85" height="58" fill="#233f52"/>`+line('M82 178v20m-30 0h60')+box(230,75,190,'Reach opportunities','Learning / care / markets')+line('M145 135H225')+dot(145+80*t,135)+box(20,260,400,'Enabling conditions','Electricity / skills / affordability / maintenance');c='Technology and networks can expand access only with supporting conditions. Tokens are information links, not measured network speed or economic gains.';}
 else if(v==='inclusion'){const open=t>.5;b=title('REMOVE BARRIERS TO PARTICIPATION')+people(55,115)+school(325,160)+line('M125 160H315')+line(open?'M220 80V125':'M220 95V225','#edaa92',7)+dot(open?235+80*(t-.5)*2:125+85*t*2,160)+T(20,270,open?'Support can open access':'Barrier: exclusion / inaccessible service',14)+T(20,315,'Language support / fair access / local knowledge',12);c='A symbolic access barrier opens in a worked example. Cultural practices and institutions are diverse and changeable; this does not assign fixed traits or ability to a community.';}
 else{b=title('INVESTMENT AND OPPORTUNITIES INTERACT')+box(20,65,180,'Investment','Skills / services / firms')+box(240,65,180,'Opportunity','Work / productivity')+box(120,250,200,'Resources','Possible reinvestment')+line('M200 100H240M330 140L230 240M120 275L65 140')+dot(200+40*t,100)+dot(330-100*t,140+100*t)+dot(120-55*t,275-135*t)+T(20,330,'Feedback is possible; distribution and demand matter.',11);c='A possible feedback loop, not a forecast or guaranteed benefit. Jobs, skills, investment and access must be considered together.';}
 }
 if(k==='dev-measures'&&v==='inequality'){const vals=incomeDistribution(Math.round(t*15)/15),sum=vals.reduce((a,b)=>a+b,0);b=title('SAME TOTAL AND MEAN, DIFFERENT DISTRIBUTION')+T(20,53,'Invented incomes · five people · 100 units total',11);for(let i=0;i<5;i++)b+=`<rect x="${30+i*80}" y="${255-vals[i]*2}" width="40" height="${vals[i]*2}" fill="${i===4?'#ecae94':'#adc5b4'}"/>`+T(30+i*80,277,String.fromCharCode(65+i),13)+T(30+i*80,299,vals[i].toFixed(1),12);b+=T(20,330,'Mean: '+(sum/5).toFixed(0)+' · Gini (0–100): '+gini(vals).toFixed(0),13);c='Invented household incomes, not national GDP shares or observed people. Transfers conserve total 100 and mean 20 while Gini rises 0→60; units of income differ from an inequality score.';return fig(b,c)+source('definition');}
 if(k==='dev-patterns'&&v==='within'){b=title('NATIONAL AVERAGES HIDE VARIATION')+box(20,65,400,'National mean income: 20 teaching units','Both invented distributions have total100 / five people')+box(20,175,190,'Distribution A','20 / 20 / 20 / 20 / 20')+box(230,175,190,'Distribution B','5 / 5 / 5 / 5 / 80')+T(20,294,'Then investigate regions, groups and households.',12);c='Two invented distributions illustrate aggregation, not actual residents or an HDI calculation. A national average does not establish uniform access or income.';}
 if(k==='dev-causes'){
 src=v==='physical'?'transport':'economy';
 if(v==='physical'){b=title('GEOGRAPHY, TRANSIT AND MARKET ACCESS')+`<path d="M335 65Q310 175 350 290H420V65Z" fill="#5f899a"/><path d="M30 240l45-100 45 100Z" fill="#8da695"/>`+box(20,70,165,'Inland producer')+box(230,230,110,'Port')+line('M100 115L200 180 280 225')+line('M202 130V230','#edba9d',2)+dot(100+180*t,115+110*t)+T(145,260,'Border / transit route',12)+T(20,325,'Agreements and infrastructure can alter costs.',12);c='Schematic inland-to-port route, not actual geography or measured costs. Terrain, infrastructure and border arrangements interact; landlocked geography does not fix development.';}
 else if(v==='history'){b=title('PAST NETWORKS CAN SHAPE PRESENT ACCESS')+box(20,65,175,'Resource area','Historic extraction')+box(245,65,175,'Export route','Trade connections')+line('M195 95H240')+dot(195+45*t,95)+school(190,235)+line('M110 140L210 220','#adc6b2',1+3*t)+T(20,190,'Local service connections',12)+T(20,325,'Inherited priorities can change through new investment.',11);c='A possible historical export-network legacy and later service investment, not every country’s colonial history. UK industrial growth and deindustrialisation are other spatially uneven legacies.';}
 else if(v==='economy'){b=title('CUMULATIVE ADVANTAGE CAN CONCENTRATE ACTIVITY')+box(110,65,220,'Firms and markets','Jobs / demand')+box(20,240,175,'Skills and suppliers')+box(245,240,175,'Finance / investment')+line('M160 140L100 230M195 260H245M330 230L280 140')+dot(160-60*t,140+90*t)+dot(195+50*t,260)+dot(330-50*t,230-90*t)+T(20,330,'Not all residents benefit; policy can change the pattern.',11);c='An illustrative feedback mechanism. London’s industry mix and UK industrial adjustment help explain why places can differ, but productivity is not household income and correlation is not proof of cause.';}
 else{b=title('EXPLAIN A PATTERN WITH CONNECTED EVIDENCE')+box(20,65,400,'Physical conditions','Terrain / resources / routes / hazards')+box(20,155,400,'Historical change','Trade / land / institutions / industry')+box(20,245,400,'Economic geography','Markets / skills / investment / policy');c='A static explanation framework. Weigh interacting factors at global and UK scales, then test them with place-specific evidence and alternative explanations.';}
 }
 return fig(b,c)+source(src);
}
